#include <cstddef>
#include <limits>
#include <new>

struct AllocationCounts {
    std::size_t allocations{};
    std::size_t deallocations{};
};

template<class T>
class CountingAllocator {
    template<class> friend class CountingAllocator;

public:
    using value_type = T;

    explicit CountingAllocator(AllocationCounts& counts) noexcept
        : counts_(&counts) {}

    // Rebind: a node container asks for CountingAllocator<Node>, and this
    // constructor is how the counter survives that conversion.
    template<class U>
    CountingAllocator(const CountingAllocator<U>& other) noexcept
        : counts_(other.counts_) {}

    T* allocate(std::size_t count) {
        // The argument is a element count, not a byte count.
        if (count > std::numeric_limits<std::size_t>::max() / sizeof(T)) {
            throw std::bad_array_new_length{};
        }
        void* storage = ::operator new(count * sizeof(T));
        ++counts_->allocations;  // only after success
        return static_cast<T*>(storage);
    }

    void deallocate(T* pointer, std::size_t) noexcept {
        ++counts_->deallocations;
        ::operator delete(pointer);
    }

    template<class U>
    bool operator==(const CountingAllocator<U>& other) const noexcept {
        return counts_ == other.counts_;  // equal means interchangeable
    }

    template<class U>
    bool operator!=(const CountingAllocator<U>& other) const noexcept {
        return !(*this == other);
    }

private:
    AllocationCounts* counts_;
};

#include <cstddef>
#include <limits>
#include <memory>
#include <new>
#include <vector>

class Arena {
public:
    Arena(std::byte* data, std::size_t capacity) noexcept
        : begin_(data), capacity_(capacity) {}

    void* allocate(std::size_t bytes, std::size_t alignment) {
        void* candidate = begin_ + used_;
        std::size_t space = capacity_ - used_;
        void* aligned = std::align(alignment, bytes, candidate, space);
        if (aligned == nullptr) {
            throw std::bad_alloc{};
        }
        used_ = static_cast<std::byte*>(aligned) - begin_ + bytes;
        return aligned;
    }

    void reset() noexcept { used_ = 0; }

private:
    std::byte* begin_;
    std::size_t capacity_;
    std::size_t used_{};
};

template<class T>
class ArenaAllocator {
    template<class> friend class ArenaAllocator;

public:
    using value_type = T;

    explicit ArenaAllocator(Arena& arena) noexcept : arena_(&arena) {}

    template<class U>
    ArenaAllocator(const ArenaAllocator<U>& other) noexcept
        : arena_(other.arena_) {}

    T* allocate(std::size_t count) {
        if (count > std::numeric_limits<std::size_t>::max() / sizeof(T)) {
            throw std::bad_array_new_length{};
        }
        return static_cast<T*>(arena_->allocate(count * sizeof(T), alignof(T)));
    }

    void deallocate(T*, std::size_t) noexcept {}  // reclaimed all at once

    template<class U>
    bool operator==(const ArenaAllocator<U>& other) const noexcept {
        return arena_ == other.arena_;  // same arena, or not interchangeable
    }

    template<class U>
    bool operator!=(const ArenaAllocator<U>& other) const noexcept {
        return !(*this == other);
    }

private:
    Arena* arena_;
};

void arena_vector_demo() {
    alignas(std::max_align_t) std::byte storage[4096];
    Arena arena{storage, sizeof(storage)};

    std::vector<int, ArenaAllocator<int>> values{ArenaAllocator<int>{arena}};
    values.reserve(16);   // one arena request for the whole buffer
    values.push_back(1);  // constructs into storage that already exists
}

#include <memory_resource>
#include <utility>
#include <vector>

struct Order {
    int id{};
    double price{};
};

void transfer(std::pmr::vector<Order>& source,
              std::pmr::vector<Order>& destination) {
    // The two vectors have the same type but unequal resources, and
    // polymorphic_allocator does not propagate on move assignment. So this
    // is O(n): the destination allocates from its own resource, each element
    // is moved across, and the source's elements are destroyed. There is no
    // pointer steal — the destination may not own the source arena's bytes.
    destination = std::move(source);

    // The source is valid but unspecified; make it explicitly empty.
    source.clear();

    // What must NOT be written here:
    //   destination.swap(source);
    // With unequal, non-propagating allocators swap is undefined behaviour,
    // not a slower path. Nothing diagnoses it: each container would end up
    // holding storage it can never correctly release.
}

#include <cstddef>
#include <cstdint>
#include <cstring>
#include <memory_resource>
#include <span>
#include <vector>

struct Fill {
    std::uint64_t order_id;
    std::int64_t price_ticks;
};

std::size_t count_fills(std::span<const std::byte> message) {
    alignas(std::max_align_t) std::byte buffer[4096];

    // null upstream: outgrowing the stack buffer throws std::bad_alloc
    // instead of quietly reaching the global heap.
    std::pmr::monotonic_buffer_resource arena{
        buffer, sizeof(buffer), std::pmr::null_memory_resource()};

    std::pmr::vector<Fill> fills{&arena};
    fills.reserve(message.size() / sizeof(Fill));

    for (std::size_t offset = 0;
         offset + sizeof(Fill) <= message.size();
         offset += sizeof(Fill)) {
        Fill fill;
        std::memcpy(&fill, message.data() + offset, sizeof(fill));
        fills.push_back(fill);
    }

    return fills.size();
}  // no individual frees: the arena and its buffer simply leave scope

#include <cstddef>
#include <memory>
#include <memory_resource>
#include <new>

class BufferResource final : public std::pmr::memory_resource {
public:
    BufferResource(std::byte* data, std::size_t capacity) noexcept
        : begin_(data), capacity_(capacity) {}

    void reset() noexcept { used_ = 0; }

private:
    void* do_allocate(std::size_t bytes, std::size_t alignment) override {
        void* candidate = begin_ + used_;
        std::size_t space = capacity_ - used_;

        void* aligned = std::align(alignment, bytes, candidate, space);
        if (aligned == nullptr) {
            throw std::bad_alloc{};  // no upstream: exhaustion is an error
        }

        used_ = static_cast<std::byte*>(aligned) - begin_ + bytes;
        return aligned;
    }

    void do_deallocate(void*, std::size_t, std::size_t) override {}

    // Equality promises that either resource may deallocate storage obtained
    // from the other. Only identity satisfies that for a bump arena, since
    // two BufferResources own disjoint buffers.
    bool do_is_equal(
        const std::pmr::memory_resource& other) const noexcept override {
        return this == &other;
    }

    std::byte* begin_;
    std::size_t capacity_;
    std::size_t used_{};
};

