struct Order {
    int id{};
    double price{};
};

class SessionBook {
public:
    explicit SessionBook(std::size_t capacity) : orders_(&resource_) {
        orders_.reserve(capacity);
    }

    void add(Order order) { orders_.push_back(std::move(order)); }

    std::size_t size() const noexcept { return orders_.size(); }

private:
    // Declaration order is the contract. Members are destroyed in reverse
    // declaration order, so orders_ is destroyed first and its final
    // deallocate call still reaches a live resource_. Swapping these two
    // lines would leave the vector's destructor with a dangling allocator.
    std::pmr::unsynchronized_pool_resource resource_;
    std::pmr::vector<Order> orders_;
};

#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <memory_resource>
#include <span>
#include <vector>

struct Fill {
    std::uint64_t order_id;
    std::int64_t price_ticks;
};

class Engine {
public:
    static constexpr std::size_t max_fills = 256;

    Engine()
        : arena_(storage_, sizeof(storage_), std::pmr::null_memory_resource()),
          pool_(make_pool_options(), &arena_),
          fills_(&pool_) {
        fills_.reserve(max_fills);
        fills_.resize(max_fills);  // warm-up: write every element once
        fills_.clear();            // keeps the capacity, drops the size
    }

    void on_message(std::span<const Fill> incoming) {
        if (incoming.size() > max_fills) {
            std::abort();  // capacity bound is part of correctness
        }

        fills_.clear();
        fills_.insert(fills_.end(), incoming.begin(), incoming.end());
    }

private:
    static std::pmr::pool_options make_pool_options() {
        std::pmr::pool_options options;
        options.max_blocks_per_chunk = 4;
        options.largest_required_pool_block = max_fills * sizeof(Fill);
        return options;
    }

    // Declaration order gives storage_, arena_ and pool_ lifetimes that
    // outlast fills_, which is destroyed first.
    alignas(std::max_align_t) std::byte storage_[64 * 1024];
    std::pmr::monotonic_buffer_resource arena_;
    std::pmr::unsynchronized_pool_resource pool_;
    std::pmr::vector<Fill> fills_;
};

#include <cstddef>
#include <cstdio>
#include <memory_resource>
#include <vector>

class CountingResource final : public std::pmr::memory_resource {
public:
    explicit CountingResource(std::pmr::memory_resource* upstream)
        : upstream_(upstream) {}

    std::size_t allocations() const noexcept { return allocations_; }
    std::size_t bytes() const noexcept { return bytes_; }

private:
    void* do_allocate(std::size_t bytes, std::size_t alignment) override {
        ++allocations_;
        bytes_ += bytes;
        return upstream_->allocate(bytes, alignment);
    }

    void do_deallocate(
        void* pointer, std::size_t bytes, std::size_t alignment) override {
        upstream_->deallocate(pointer, bytes, alignment);
    }

    bool do_is_equal(
        const std::pmr::memory_resource& other) const noexcept override {
        return this == &other;
    }

    std::pmr::memory_resource* upstream_;
    std::size_t allocations_ = 0;
    std::size_t bytes_ = 0;
};

bool audit_reserved_vector() {
    CountingResource counter{std::pmr::new_delete_resource()};

    std::pmr::vector<int> prices{&counter};
    prices.reserve(1'000);
    for (int i = 0; i < 1'000; ++i) {
        prices.push_back(i);
    }

    std::printf("%zu allocations, %zu bytes\n",
                counter.allocations(), counter.bytes());
    return counter.allocations() == 1;
}
